	ACMPHS0_CMPCTL_COE = 0x2
	// Disable comparator output (output signal is low level)
	ACMPHS0_CMPCTL_COE_0 = 0x0
	// Enable comparator output
	ACMPHS0_CMPCTL_COE_1 = 0x1
