	IIC_B0_SVCTL_DVIDE_Pos = 0x6
	// Bit mask of DVIDE field.
	IIC_B0_SVCTL_DVIDE_Msk = 0x40
	// Bit DVIDE.
	IIC_B0_SVCTL_DVIDE = 0x40
	// Device-ID address detection disables.
	IIC_B0_SVCTL_DVIDE_0 = 0x0
	// Device-ID address detection enables.
	IIC_B0_SVCTL_DVIDE_1 = 0x1
	// Position of HOAE field.
