	// Bit mask of SVAE0 field.
	IIC_B0_SVCTL_SVAE0_Msk = 0x10000
	// Bit SVAE0.
	IIC_B0_SVCTL_SVAE0 = 0x10000
	// Slave 0 disables
	IIC_B0_SVCTL_SVAE0_0 = 0x0
	// Slave 0 enables
	IIC_B0_SVCTL_SVAE0_1 = 0x1
	// Position of SVAE1 field.
	IIC_B0_SVCTL_SVAE1_Pos = 0x11
	// Bit mask of SVAE1 field.
	IIC_B0_SVCTL_SVAE1_Msk = 0x20000
	// Bit SVAE1.
	IIC_B0_SVCTL_SVAE1 = 0x20000
	// Slave 1 disables
	IIC_B0_SVCTL_SVAE1_0 = 0x0
	// Slave 1 enables
	IIC_B0_SVCTL_SVAE1_1 = 0x1
	// Position of SVAE2 field.
