	IIC_B0_REFCKCTL_IREFCKS_010 = 0x2
	// IICCLK/8 clock
	IIC_B0_REFCKCTL_IREFCKS_011 = 0x3
	// IICCLK/16 clock
	IIC_B0_REFCKCTL_IREFCKS_100 = 0x4
	// IICCLK/32 clock
	IIC_B0_REFCKCTL_IREFCKS_101 = 0x5
	// IICCLK/64 clock
	IIC_B0_REFCKCTL_IREFCKS_110 = 0x6
	// IICCLK/128 clock
	IIC_B0_REFCKCTL_IREFCKS_111 = 0x7

