	IIC_B0_STDBR_DSBRPO_Pos = 0x1f
	// Bit mask of DSBRPO field.
	IIC_B0_STDBR_DSBRPO_Msk = 0x80000000
	// Bit DSBRPO.
	IIC_B0_STDBR_DSBRPO = 0x80000000
	// The time period set for SBRHO[7:0] and SBRLO[7:0] is not doubled.
