	IIC_B0_OUTCTL_SCOC_Pos = 0x1
	// Bit mask of SCOC field.
	IIC_B0_OUTCTL_SCOC_Msk = 0x2
	// Bit SCOC.
	IIC_B0_OUTCTL_SCOC = 0x2
	// IIC drives the SCLn pin low.
	IIC_B0_OUTCTL_SCOC_0 = 0x0
	// IIC releases the SCLn pin.
	IIC_B0_OUTCTL_SCOC_1 = 0x1
	// Position of SOCWP field.
	IIC_B0_OUTCTL_SOCWP_Pos = 0x2
	// Bit mask of SOCWP field.
	IIC_B0_OUTCTL_SOCWP_Msk = 0x4
	// Bit SOCWP.
	IIC_B0_OUTCTL_SOCWP = 0x4
	// Bits SCOC and SDOC are protected.
	IIC_B0_OUTCTL_SOCWP_0 = 0x0
	// Bits SCOC and SDOC can be written (When writing simultaneously with the value of the target bit). This bit is read as 0.
	IIC_B0_OUTCTL_SOCWP_1 = 0x1
