	// 6bit-timeout
	IIC_B0_TMOCTL_TODTS_11 = 0x3
	// Position of TOLCTL field.
	IIC_B0_TMOCTL_TOLCTL_Pos = 0x4
	// Bit mask of TOLCTL field.
	IIC_B0_TMOCTL_TOLCTL_Msk = 0x10
	// Bit TOLCTL.
	IIC_B0_TMOCTL_TOLCTL = 0x10
	// Count is disabled while the SCLn line is at a low level.
	IIC_B0_TMOCTL_TOLCTL_0 = 0x0
	// Count is enabled while the SCLn line is at a low level.
	IIC_B0_TMOCTL_TOLCTL_1 = 0x1
	// Position of TOHCTL field.
	IIC_B0_TMOCTL_TOHCTL_Pos = 0x5
	// Bit mask of TOHCTL field.
	IIC_B0_TMOCTL_TOHCTL_Msk = 0x20
	// Bit TOHCTL.
	IIC_B0_TMOCTL_TOHCTL = 0x20
	// Count is disabled while the SCLn line is at a high level.
	IIC_B0_TMOCTL_TOHCTL_0 = 0x0
	// Count is enabled while the SCLn line is at a high level.
	IIC_B0_TMOCTL_TOHCTL_1 = 0x1
	// Position of TOMDS field.
	IIC_B0_TMOCTL_TOMDS_Pos = 0x6
	// Bit mask of TOMDS field.
	IIC_B0_TMOCTL_TOMDS_Msk = 0xc0
	// Timeout is detected during the following conditions: The bus is busy (BCST.BFREF = 0) in master mode.IIC’s own slave address is detected and the bus is busy in slave mode.The bus is free (BCST.BFREF = 1) while generation of a START condition is requested (CNDCTL.STCND = 1).
	IIC_B0_TMOCTL_TOMDS_00 = 0x0
	// Timeout is detected while the bus is busy.
	IIC_B0_TMOCTL_TOMDS_01 = 0x1
	// Timeout is detected while the bus is free.
	IIC_B0_TMOCTL_TOMDS_10 = 0x2
	// Setting prohibited
	IIC_B0_TMOCTL_TOMDS_11 = 0x3

