	// The ACKT bit are protected.
	IIC_B0_ACKCTL_ACKTWP_0 = 0x0
	// The ACKT bit can be written (when writing simultaneously with the value of the target bit). This bit is read as 0.
	IIC_B0_ACKCTL_ACKTWP_1 = 0x1

