	ADC_B_ADCLKENR_CLKEN = 0x1
	// Stop ADCLK
	ADC_B_ADCLKENR_CLKEN_0 = 0x0
	// Supply ADCLK
	ADC_B_ADCLKENR_CLKEN_1 = 0x1

	// ADCLKSR: A/D Conversion Clock Status Register
