	ADC_B_ADCLKSR_CLKSR_Pos = 0x0
	// Bit mask of CLKSR field.
	ADC_B_ADCLKSR_CLKSR_Msk = 0x1
	// Bit CLKSR.
	ADC_B_ADCLKSR_CLKSR = 0x1
	// ADCLK is stopped
	ADC_B_ADCLKSR_CLKSR_0 = 0x0
	// ADCLK is in supply
	ADC_B_ADCLKSR_CLKSR_1 = 0x1

	// ADCLKCR: A/D Conversion Clock Control Register
	// Position of CLKSEL field.
	ADC_B_ADCLKCR_CLKSEL_Pos = 0x0
	// Bit mask of CLKSEL field.
	ADC_B_ADCLKCR_CLKSEL_Msk = 0x3
