	ADC_B_ADCLKCR_CLKSEL_00 = 0x0
	// GPT clock (GPTCLK)
	ADC_B_ADCLKCR_CLKSEL_01 = 0x1
	// Peripheral Module Clock A (PCLKA)
	ADC_B_ADCLKCR_CLKSEL_10 = 0x2
	// Position of DIVR field.
	ADC_B_ADCLKCR_DIVR_Pos = 0x10
	// Bit mask of DIVR field.
	ADC_B_ADCLKCR_DIVR_Msk = 0x70000
	// 1/1
	ADC_B_ADCLKCR_DIVR_000 = 0x0
	// 1/2
	ADC_B_ADCLKCR_DIVR_001 = 0x1
	// 1/3
	ADC_B_ADCLKCR_DIVR_010 = 0x2
	// 1/4
	ADC_B_ADCLKCR_DIVR_011 = 0x3
	// 1/5
	ADC_B_ADCLKCR_DIVR_100 = 0x4
	// 1/6
	ADC_B_ADCLKCR_DIVR_101 = 0x5
	// 1/7
	ADC_B_ADCLKCR_DIVR_110 = 0x6
	// 1/8
	ADC_B_ADCLKCR_DIVR_111 = 0x7

	// ADSYCR: A/D Converter Synchronous Operation Control Register
	// Position of ADSYCYC field.
	ADC_B_ADSYCR_ADSYCYC_Pos = 0x0
	// Bit mask of ADSYCYC field.
	ADC_B_ADSYCR_ADSYCYC_Msk = 0x7ff
