	ADC_B_ADSYCR_ADSYDIS0_Pos = 0x10
	// Bit mask of ADSYDIS0 field.
	ADC_B_ADSYCR_ADSYDIS0_Msk = 0x10000
	// Bit ADSYDIS0.
	ADC_B_ADSYCR_ADSYDIS0 = 0x10000
	// Enable ADC0 synchronous operation
	ADC_B_ADSYCR_ADSYDIS0_0 = 0x0
	// Disable ADC0 synchronous operation
	ADC_B_ADSYCR_ADSYDIS0_1 = 0x1
	// Position of ADSYDIS1 field.
	ADC_B_ADSYCR_ADSYDIS1_Pos = 0x11
	// Bit mask of ADSYDIS1 field.
	ADC_B_ADSYCR_ADSYDIS1_Msk = 0x20000
	// Bit ADSYDIS1.
	ADC_B_ADSYCR_ADSYDIS1 = 0x20000
	// Enable ADC1 synchronous operation
	ADC_B_ADSYCR_ADSYDIS1_0 = 0x0
	// Disable ADC1 synchronous operation
	ADC_B_ADSYCR_ADSYDIS1_1 = 0x1

