	ADC_B_ADGSPCR_PGS0_Pos = 0x0
	// Bit mask of PGS0 field.
	ADC_B_ADGSPCR_PGS0_Msk = 0x1
	// Bit PGS0.
	ADC_B_ADGSPCR_PGS0 = 0x1
	// ADC0 operation is without group priority control
	ADC_B_ADGSPCR_PGS0_0 = 0x0
	// ADC0 operation is with group priority control in SAR mode. Setting prohibited when other than SAR mode.
	ADC_B_ADGSPCR_PGS0_1 = 0x1
	// Position of RSCN0 field.
	ADC_B_ADGSPCR_RSCN0_Pos = 0x1
	// Bit mask of RSCN0 field.
	ADC_B_ADGSPCR_RSCN0_Msk = 0x2
	// Bit RSCN0.
	ADC_B_ADGSPCR_RSCN0 = 0x2
	// Set when PGS0 is set to 0.
