	// Position of DAAMP0 field.
	DAC120_DAAMPCR_DAAMP0_Pos = 0x6
	// Bit mask of DAAMP0 field.
	DAC120_DAAMPCR_DAAMP0_Msk = 0x40
	// Bit DAAMP0.
	DAC120_DAAMPCR_DAAMP0 = 0x40
	// Do not use channel 0 output amplifier (m = 0) Do not use channel 2 output amplifier (m = 1)
	DAC120_DAAMPCR_DAAMP0_0 = 0x0
	// Use channel 0 output amplifier (m = 0) Use channel 2 output amplifier (m = 1)
	DAC120_DAAMPCR_DAAMP0_1 = 0x1
